#!/usr/bin/env python3
"""Validates: selected quotations occur verbatim at the recorded private-log lines.

Requires the private provenance files generated by the two census scripts. Only
the allowlisted excerpts below are exported, never arbitrary messages/tool data.
These are qualitative selections, not a random sample or task-success labels.
"""
import argparse, hashlib, json
from pathlib import Path
from session_census import opened, DEFAULT_OUTPUT

SELECTIONS = [
 ('codex','01a169b1-4495-7152-bd98-79d79092095a',10,'(work on a worktree) seek improvements in the way this codebase is structured that could lead to large red diffs. tell me your ideas.','human','circuit-refactor'),
 ('codex','01a169b1-4495-7152-bd98-79d79092095a',224,'Please pursue 1. Let synthesis proofs track available wires automatically.','human','circuit-refactor'),
 ('codex','01a169b1-4495-7152-bd98-79d79092095a',390,"Do you think we're going to be able to build circuits which are efficient this way, or are we going to be introducing a lot of subtle inefficiencies?",'human','circuit-refactor'),
 ('codex','01a169b1-4495-7152-bd98-79d79092095a',1637,'Existing statements and size bounds are preserved. Requested budgets are checked; choosing cheaper constructions remains explicit.','assistant-report','circuit-refactor'),
 ('codex','01a169b1-4495-7152-bd98-79d79092095a',1644,'Is this clear to a human reader?','human','circuit-refactor'),
 ('codex','01a169b1-4495-7152-bd98-79d79092095a',1748,"I feel like the budget-guided synthesis isn't really helpful maybe, don't read too much into that.",'human','circuit-refactor'),
 ('codex','01a16585-a242-7713-91d3-431e60c353f4',10,'Please inspect the accuracy of our claims and the code quality and drift from possible human intent or meaning.','human','headline-curation'),
 ('codex','01a16585-a242-7713-91d3-431e60c353f4',374,"Let's build intuitive, high quality abstracts for all of the major headline results.",'human','headline-curation'),
 ('codex','01a16585-a242-7713-91d3-431e60c353f4',957,"Let's also try to have a higher bar for the theorems we broadcast as headlines.",'human','headline-curation'),
 ('codex','01a16585-a242-7713-91d3-431e60c353f4',961,'We should make the smaller number all have abstracts and potentially abandon the paper/ tex list too','human','headline-curation'),
 ('codex','01a1661d-bea5-7cf3-8863-7095a0b208dc',516,"Yes, indeed. Look at the roadmap and what we've closed off of it. We had some really ambitious theorems, some of which we botched and rolled back",'human','theorem-recovery'),
 ('codex','01a1661d-bea5-7cf3-8863-7095a0b208dc',1070,"Let's recover each of the ambitious theorem goals in sequence, reestablishing the credibility of the autonomous review and development loop.",'human','theorem-recovery'),
 ('codex','01a1661d-bea5-7cf3-8863-7095a0b208dc',2487,"And this time we're going to do each of them at a high standard where they actually encode the true statement of the theorem, we're going to take our time to get this work done instead of rushing and getting a hacky version of it out like happened before",'human','theorem-recovery'),
 ('codex','01a1661d-bea5-7cf3-8863-7095a0b208dc',4139,'Coordinators should be fairly sure such ideas are good ones when accepting them, not just acceepting arbitrary programming conventions.','human','api-ergonomics'),
 ('claude','0ee2da73-c178-4fc8-86c0-8241ee284c9b',7,'What is the current state of RAM computation in here and proof automation around it?','human','ram-integration'),
 ('claude','0ee2da73-c178-4fc8-86c0-8241ee284c9b',545,'So it sounds like we should integrate both definitions.','human','ram-integration'),
 ('claude','0ee2da73-c178-4fc8-86c0-8241ee284c9b',566,"Perfect. Let's become a worker and integrate Demain's work and credit him or whoever else is an author in the original work in the files as an author.",'human','ram-integration'),
 ('claude','397e0b7e-0e98-445f-a58e-013e72aafef3',7,'are there useful ways we could improve compilation speed and developer ergonomics in this system, especially for AIs','human','build-cache'),
 ('claude','397e0b7e-0e98-445f-a58e-013e72aafef3',410,"We should probably scan those worktrees for interesting diffs that have work we don't want to lose.",'human','build-cache'),
 ('claude','397e0b7e-0e98-445f-a58e-013e72aafef3',742,'Can we deploy our own cache for complexitylib itself?','human','build-cache'),
 ('claude','99a1aa4d-7729-44fd-9fab-3fab6ee2dc0a',129,'Are there any misformalized things present on main now','human','followup-audit'),
 ('claude','99a1aa4d-7729-44fd-9fab-3fab6ee2dc0a',1142,"Yes, after this work let's look into profiling the longest proofs.",'human','followup-audit'),
]

def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('private_provenance');ap.add_argument('--output',type=Path,default=DEFAULT_OUTPUT/'transcript_excerpts.json');a=ap.parse_args()
    b=Path(a.private_provenance)
    codex=json.loads((b/'session_provenance.json').read_text())['metadata']
    claude=json.loads((b/'claude_provenance.json').read_text())
    out=[];cache={}
    for provider,sid,line,quote,role,case in SELECTIONS:
        if (provider,sid) not in cache:
            if provider=='codex':p=Path(next(m['path'] for m in codex if m['id']==sid))
            else:p=Path(next(m['path'] for m in claude if m['source_basename']==sid+'.jsonl'))
            with opened(p) as f:raw=f.read()
            cache[provider,sid]=(p.name,hashlib.sha256(raw.encode()).hexdigest(),raw.splitlines())
        name,digest,lines=cache[provider,sid];rawline=lines[line-1];x=json.loads(rawline)
        if provider=='codex':m=x['payload'];actual_role=m.get('role');content=m.get('content',[])
        else:m=x.get('message',{});actual_role=x.get('type');content=m.get('content',[])
        content=content if isinstance(content,str) else '\n'.join(c.get('text','') for c in content if isinstance(c,dict))
        assert quote in content,(sid,line,'quote not found')
        assert actual_role==('user' if role=='human' else 'assistant'),(sid,line,'role mismatch')
        out.append({'excerpt_id':f'e{len(out)+1:02d}','provider':provider,'session_id':sid,'source_basename':name,'uncompressed_sha256':digest,'record_line':line,'record_timestamp':x.get('timestamp'),'record_sha256':hashlib.sha256(rawline.encode()).hexdigest(),'role':role,'case':case,'excerpt':quote,'selection':'Verbatim substring; surrounding context omitted. Spelling preserved. No tool arguments or account data exported.'})
    a.output.parent.mkdir(parents=True,exist_ok=True)
    a.output.write_text(json.dumps(out,indent=2)+'\n');print(f'Validated {len(out)} excerpts from {len(cache)} source files')
if __name__=='__main__':main()
